#!/usr/bin/env python3
import sys
import rclpy
from rclpy.node import Node
from rclpy.qos import QoSProfile, ReliabilityPolicy, HistoryPolicy
from std_msgs.msg import String, Int32MultiArray
from std_srvs.srv import Trigger
from dex_hand_ros2.msg import GestureCmd, MotorState, PIDconfig


from dex_hand_ros2.srv import AddGesture, RunGesturePid
from .hand_driver import (MPD20Driver, RoboticHand, FeetechDriver,
                             HTS20LDriver, FakeMotorDriver, GenericMotorDriver)
import time
from typing import Dict, Optional

class DexHandROS2Node(Node):
    def __init__(self):
        super().__init__("dex_hand_node")

        # 参数声明
        self.declare_parameter("serial_port", "/dev/ttyUSB0")
        self.declare_parameter("baudrate", 115200)
        self.declare_parameter("driver_type", "mpd20")   # 新增：可选择驱动类型 mpd20/feetech/fake
        self.declare_parameter("status_pub_freq", 10.0)
        self.declare_parameter("pid_kp", 2.0)
        self.declare_parameter("pid_ki", 0.1)
        self.declare_parameter("pid_kd", 0.05)

        port = self.get_parameter("serial_port").get_parameter_value().string_value
        baudrate = self.get_parameter("baudrate").get_parameter_value().integer_value
        driver_type = self.get_parameter("driver_type").get_parameter_value().string_value
        self.status_freq = self.get_parameter("status_pub_freq").get_parameter_value().double_value
        default_kp = self.get_parameter("pid_kp").get_parameter_value().double_value
        default_ki = self.get_parameter("pid_ki").get_parameter_value().double_value
        default_kd = self.get_parameter("pid_kd").get_parameter_value().double_value

        # 根据类型创建驱动
        if driver_type == "feetech":
            self.driver = FeetechDriver(port, baudrate)
        elif driver_type == "hts20l":
            self.driver = HTS20LDriver(port, baudrate)
        elif driver_type == "fake":
            self.driver = FakeMotorDriver(port, baudrate)
        else:
            self.driver = MPD20Driver(port, baudrate)

        if not self.driver.connect():
            self.get_logger().error(f"串口连接失败: {port}")
            raise RuntimeError(f"无法连接到 {port}")  # 终止节点启动

        self.hand = RoboticHand(self.driver)
        # 初始化所有电机的 PID 参数
        for motor_id in range(1, 7):
            self.driver.set_pid_params(motor_id, default_kp, default_ki, default_kd)
        self.get_logger().info(f"机械手连接成功，驱动类型: {driver_type}，PID 默认 Kp={default_kp} Ki={default_ki} Kd={default_kd}")

        # QoS 配置
        qos = QoSProfile(
            reliability=ReliabilityPolicy.RELIABLE,
            history=HistoryPolicy.KEEP_LAST,
            depth=10
        )

        # 发布者
        self.status_pub = self.create_publisher(String, "/dex_hand/status", qos)
        self.motor_state_pub = self.create_publisher(MotorState, "/dex_hand/motor_state", qos)

        # 订阅者
        self.gesture_cmd_sub = self.create_subscription(
            GestureCmd, "/dex_hand/gesture_cmd", self.gesture_cmd_callback, qos)
        self.motor_pos_sub = self.create_subscription(
            Int32MultiArray, "/dex_hand/motor_pos_cmd", self.motor_pos_callback, qos)
        self.motor_pos_pid_sub = self.create_subscription(
            Int32MultiArray, "/dex_hand/motor_pos_pid_cmd", self.motor_pos_pid_callback, qos)
        self.pid_config_sub = self.create_subscription(
            PIDconfig, "/dex_hand/pid_config", self.pid_config_callback, qos)

        # 服务（使用自定义服务替换 Trigger）
        self.list_gestures_srv = self.create_service(
            Trigger, "/dex_hand/list_gestures", self.list_gestures_callback)
        self.demo_gestures_srv = self.create_service(
            Trigger, "/dex_hand/demo_gestures", self.demo_gestures_callback)
        self.add_gesture_srv = self.create_service(
            AddGesture, "/dex_hand/add_gesture", self.add_gesture_callback)
        self.run_gesture_pid_srv = self.create_service(
            RunGesturePid, "/dex_hand/run_gesture_pid", self.run_gesture_pid_callback)

        # 定时器
        self.status_timer = self.create_timer(1.0/self.status_freq, self.publish_status)

        # 内部状态
        self._gesture_names = ["open", "fist", "vgesture"]  # 用于演示
        self._demo_timer = None
        self._demo_cursor = 0

    # ==================== 回调实现 ====================
    def gesture_cmd_callback(self, msg: GestureCmd):
        speed = float(msg.speed) if msg.speed > 0 else 1.0
        success = self.hand.run_gesture(msg.gesture, speed)
        if success:
            self.get_logger().info(f"执行手势: {msg.gesture}, 速度: {speed}")
        else:
            self.get_logger().error(f"手势执行失败: {msg.gesture}")

    def motor_pos_callback(self, msg: Int32MultiArray):
        if len(msg.data) < 2:
            self.get_logger().error("电机位置指令格式错误，需要 [motor_id, position]")
            return
        motor_id, position = msg.data[0], msg.data[1]
        if 1 <= motor_id <= 6 and 0 <= position <= 100:
            if self.hand.set_motor_position(motor_id, position):
                self.get_logger().info(f"电机 {motor_id} 设为 {position}%")
            else:
                self.get_logger().error(f"电机 {motor_id} 设置失败")
        else:
            self.get_logger().error(f"参数非法: ID={motor_id}, 位置={position}")

    def motor_pos_pid_callback(self, msg: Int32MultiArray):
        if len(msg.data) < 2:
            self.get_logger().error("PID 指令格式错误，需要 [motor_id, position]")
            return
        motor_id, target = msg.data[0], msg.data[1]
        if 1 <= motor_id <= 6 and 0 <= target <= 100:
            if self.driver.set_position_with_pid(motor_id, target):
                self.get_logger().info(f"PID 电机 {motor_id} 到位: {target}%")
            else:
                self.get_logger().error(f"PID 电机 {motor_id} 失败")
        else:
            self.get_logger().error(f"PID 参数非法: ID={motor_id}, 目标={target}")

    def pid_config_callback(self, msg: PIDconfig):
        if 1 <= msg.motor_id <= 6:
            self.driver.set_pid_params(msg.motor_id, msg.kp, msg.ki, msg.kd)
            self.get_logger().info(f"配置电机 {msg.motor_id} PID: Kp={msg.kp}, Ki={msg.ki}, Kd={msg.kd}")
        else:
            self.get_logger().error(f"电机 ID {msg.motor_id} 超出范围")

    def list_gestures_callback(self, request, response):
        gestures = self.hand.get_gesture_list()
        response.success = True
        response.message = ", ".join(gestures)
        return response

    def demo_gestures_callback(self, request, response):
        if self._demo_timer is not None:
            response.success = False
            response.message = "演示正在进行中，请稍后再试"
            return response
        self._demo_cursor = 0
        self._demo_timer = self.create_timer(1.0, self._demo_step)
        self.get_logger().info("开始手势演示")
        response.success = True
        response.message = "演示开始"
        return response

    def _demo_step(self):
        if self._demo_cursor >= len(self._gesture_names):
            if self._demo_timer is not None:
                self.destroy_timer(self._demo_timer)
            self._demo_timer = None
            self.get_logger().info("演示完成")
            return
        name = self._gesture_names[self._demo_cursor]
        self.hand.run_gesture(name)
        self.get_logger().info(f"演示手势: {name}")
        self._demo_cursor += 1

    def add_gesture_callback(self, request, response):
        self.hand.add_gesture(request.name, dict(enumerate(request.positions, start=1)),
                              request.description, request.duration)
        response.success = True
        response.message = f"添加手势 {request.name} 成功"
        return response

    def run_gesture_pid_callback(self, request, response):
        success = self.hand.run_gesture_with_pid(request.gesture_name)
        response.success = success
        response.message = "PID 手势成功" if success else "PID 手势失败"
        return response

    # ==================== 状态发布 ====================
    def publish_status(self):
        msg = String()
        msg.data = "Hand online" if self.driver.is_connected() else "Disconnected"
        self.status_pub.publish(msg)

        # 可选：发布详细 MotorState
        # state = MotorState()
        # for i in range(1, 7):
        #     pos = self.driver.get_position(i)
        #     state.motor_id.append(i)
        #     state.position.append(pos if pos is not None else -1)
        # self.motor_state_pub.publish(state)

    def destroy_node(self):
        if self._demo_timer is not None:
            self.destroy_timer(self._demo_timer)
            self._demo_timer = None
        if hasattr(self, 'driver') and self.driver:
            self.driver.disconnect()
        super().destroy_node()


def main(args=None):
    rclpy.init(args=args)
    node = None
    try:
        node = DexHandROS2Node()
        rclpy.spin(node)
    except KeyboardInterrupt:
        if node:
            node.get_logger().info("用户中断")
    except Exception as e:
        print(f"节点启动失败: {e}", file=sys.stderr)
    finally:
        if node:
            node.destroy_node()
        rclpy.shutdown()

if __name__ == "__main__":
    main()